import json, os, resource, sys
from pathlib import Path
source, stage=sys.argv[1:]
def snapshot(name):
    fields={}
    for line in Path('/proc/self/status').read_text().splitlines():
        if line.startswith(('VmRSS:','VmHWM:')):
            key,value,*_=line.split(); fields[key.rstrip(':')]=int(value)*1024
    print(json.dumps({'stage':name,'pid':os.getpid(),'VmRSS_bytes':fields['VmRSS'],'VmHWM_bytes':fields['VmHWM'],'ru_maxrss_bytes':resource.getrusage(resource.RUSAGE_SELF).ru_maxrss*1024}),flush=True)
if stage=='fork':
    pid=os.fork()
    if pid==0: os.execv(sys.executable,[sys.executable,'-c',source,source,'allocate'])
    _,status=os.waitpid(pid,0); sys.exit(os.waitstatus_to_exitcode(status))
if stage=='allocate':
    snapshot('before_allocation')
    storage=bytearray(32*1024*1024)
    for offset in range(0,len(storage),4096): storage[offset]=1
    snapshot('before_exec_after_32MiB_touch')
    os.execv(sys.executable,[sys.executable,'-c',source,source,'after_exec'])
else: snapshot('after_exec_same_pid')
